/* Print247 Editorial Review • static, read-only, source-preserving dashboard */
(() => {
  'use strict';
  const D = window.PRINT247_AUDIT_DATA;
  const root = document.getElementById('app');
  const modalRoot = document.getElementById('modal-root');
  if (!D) {root.innerHTML='<div class="boot">Audit data could not be loaded.</div>';return;}

  const htmlEsc = v => String(v ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
  const h = htmlEsc;
  const fmt = n => Number(n||0).toLocaleString('en-US');
  const fixed = n => typeof n === 'number' ? n.toFixed(1) : '—';
  const lower = s => String(s||'').toLowerCase();
  const articles = D.articles;
  const allWriters = D.writers;
  const getArticle = id => articles.find(a=>a.id===id);
  const getWriter = slug => allWriters.find(w=>w.slug===slug);
  const slug = s => String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  const writerUrl = writer => `/writers/${slug(writer)}`;
  const articleUrl = a => `/writers/${slug(a.writer)}/articles/${a.number}`;
  const originalUrl = a => `/data/original/${a.id}.json`;
  const maxLine = (v,n=115) => {v=String(v||'');return v.length>n?v.slice(0,n-1).trim()+'…':v;};
  const icons = {
    dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
    book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/>',
    file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',
    chart:'<path d="M3 3v18h18"/><path d="m7 14 4-5 3 3 5-7"/>',
    check:'<path d="M20 6 9 17l-5-5"/>',
    x:'<path d="M18 6 6 18M6 6l12 12"/>',
    alert:'<path d="m10.3 3.8-8.1 14a2 2 0 0 0 1.7 3h16.2a2 2 0 0 0 1.7-3l-8.1-14a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/>',
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    chevron:'<path d="m9 18 6-6-6-6"/>',
    chevrondown:'<path d="m6 9 6 6 6-6"/>',
    export:'<path d="M12 3v12m-4-4 4 4 4-4"/><path d="M4 17v3a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-3"/>',
    external:'<path d="M14 3h7v7M10 14 21 3"/><path d="M21 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h6"/>',
    image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 15-5-5L5 21"/>',
    search:'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>',
    menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
    shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10"/><path d="m9 12 2 2 4-4"/>',
    info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',
    copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',
    print:'<path d="M6 9V2h12v7M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v8H6z"/>',
    filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',
    target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
    bulb:'<path d="M9 18h6m-5 4h4m-5-7c-2-1.3-3-3.5-3-6a6 6 0 1 1 12 0c0 2.5-1 4.7-3 6l-1 2h-4z"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'
  };
  const ic = (name,cl='icon') => `<svg class="${h(cl)}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`;
  let threshold = 70;
  let articleTab = 'summary';
  let checkFilter = 'all';
  let checkSearch = '';
  let issueFilter = 'all';
  let openGroups = {};
  let viewedIssue = null;
  let menuOpen = false;
  let reviewed = {};
  try {const a=Number(localStorage.getItem('p247_threshold'));if(a>=50&&a<=90)threshold=a;reviewed=JSON.parse(localStorage.getItem('p247_reviewed')||'{}')} catch(e){}

  function statusBadge(s,label){const statuses={pass:['pass','PASS'],fail:['fail','FAIL'],na:['na','N/A'],not_verified:['nv','NOT VERIFIED'],nv:['nv','NOT VERIFIED'],review:['review','REVIEW']};const v=statuses[s]||statuses.na;return `<span class="badge ${v[0]}"><span class="status-dot"></span>${h(label||v[1])}</span>`;}
  function severityBadge(s){const labels={critical:['fail','CRITICAL'],major:['fail','MAJOR'],moderate:['nv','MODERATE'],minor:['na','MINOR']};const a=labels[s]||labels.moderate;return `<span class="badge ${a[0]}">${h(a[1])}</span>`;}
  function thresholdLabel(score, critical=0){if(score<threshold)return statusBadge('fail','BELOW BENCHMARK');if(critical>0)return statusBadge('review','REVIEW CRITICAL ISSUES');return statusBadge('pass','MEETS NUMERIC BENCHMARK');}
  function scoreBar(v){return `<div class="score-track"><div class="score-fill ${v<60?'low':''}" style="width:${Math.max(0,Math.min(100,v))}%"></div></div>`;}
  function percentBar(v){return `<div class="barline"><span class="${v<3?'low':''}" style="width:${Math.max(0,Math.min(100,(v||0)*20))}%"></span></div>`;}
  function avatar(name){return h(name.slice(0,2).toUpperCase());}
  function stat(label,value,note,cls=''){return `<div class="card stat"><div class="stat-label">${h(label)}</div><div class="stat-value mono ${cls}">${h(value)}</div><div class="stat-note">${h(note||'')}</div></div>`;}
  function footer(){return `<footer class="footer-disclaimer">${ic('info')}<div><strong>Source & evaluation notice.</strong> Consolidated from 18 previously prepared audit JSON files. Scores are provisional editorial judgments, not validated personnel performance measures. Evidence images are annotated article excerpts, not real webpage screenshots. 40 diagnostic checks are marked Not verified, and Maryam has three reviewed articles versus five for the other writers. Scores and source notes have not been silently modified.</div></footer>`;}
  function navItem(label,path,icon,active,extra=''){return `<a data-link href="${path}" class="nav-link ${active?'active':''}">${ic(icon,'icon nav-icon')}<span>${h(label)}</span>${extra?`<span class="nav-counter">${h(extra)}</span>`:''}</a>`;}
  function sidebar(path){return `<aside class="sidebar ${menuOpen?'open':''}" aria-label="Main navigation"><a class="brand" href="/" data-link><div class="brand-mark">P<span style="font-size:11px">7</span></div><div><div class="brand-title">Print247</div><div class="brand-sub">Editorial intelligence</div></div></a><div class="nav-group-label">Workspace</div>${navItem('Overview','/','dashboard',path==='/')}${navItem('Writer rankings','/rankings','chart',path==='/rankings')}${navItem('Evaluation criteria','/criteria','book',path==='/criteria')}<div class="nav-group-label">Writers · ${D.writers.length}</div>${allWriters.map(w=>`<a data-link class="nav-link ${path.startsWith(writerUrl(w.name))?'active':''}" href="${writerUrl(w.name)}"><span class="nav-avatar">${avatar(w.name)}</span><span>${h(w.name)}</span><span class="nav-counter">${fixed(w.average)}</span></a>`).join('')}<div class="nav-group-label">Resources</div>${navItem('Data & limitations','/about','shield',path==='/about')}<div class="sidebar-foot"><small><strong>18 articles · 4 writers</strong></small><small>Read-only review workspace</small><small>Audits compiled October 2026</small></div></aside>`;}
  function parseRoute(){const path=decodeURI(location.pathname).replace(/\/+$/,'')||'/';let m=path.match(/^\/writers\/([a-z]+)\/articles\/(\d+)$/);if(m)return {path,type:'article',writer:m[1],number:+m[2]};m=path.match(/^\/writers\/([a-z]+)$/);if(m)return{path,type:'writer',writer:m[1]};if(path==='/rankings')return{path,type:'rankings'};if(path==='/criteria')return{path,type:'criteria'};if(path==='/about')return{path,type:'about'};if(path==='/')return{path,type:'home'};return{path,type:'404'};}
  function crumb(route){const pieces=[`<a href="/" data-link>Workspace</a>`];if(route.type==='home')pieces.push('<span class="slash">/</span><strong>Overview</strong>');else if(route.type==='rankings')pieces.push('<span class="slash">/</span><strong>Writer rankings</strong>');else if(route.type==='criteria')pieces.push('<span class="slash">/</span><strong>Evaluation criteria</strong>');else if(route.type==='about')pieces.push('<span class="slash">/</span><strong>Data & limitations</strong>');else if(route.type==='writer'||route.type==='article'){const w=getWriter(route.writer);pieces.push(`<span class="slash">/</span><a data-link href="/rankings">Writers</a><span class="slash">/</span>${route.type==='writer'?`<strong>${h(w?.name||'Unknown')}</strong>`:`<a data-link href="/writers/${route.writer}">${h(w?.name||'Unknown')}</a><span class="slash">/</span><strong>Article ${route.number}</strong>`}`)}return pieces.join('');}
  function appShell(route,content){return `<div class="app-shell">${sidebar(route.path)}<div class="mobile-overlay ${menuOpen?'open':''}" data-action="closemenu"></div><main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:13px"><button class="drawer-toggle" aria-label="Open navigation" data-action="menu">${ic('menu')}</button><div class="mobile-title">Print247 Review</div><div class="crumb">${crumb(route)}</div></div><div class="top-actions"><span class="top-pill">● &nbsp; EVIDENCE-BASED REVIEW</span><button class="btn" data-action="export-overall">${ic('export')}<span> Export data</span></button></div></header><div class="view">${content}${footer()}</div></main></div>`;}

  function dashboard(){const t=D.totals;const crit=articles.flatMap(a=>a.issues.filter(i=>i.severity==='critical').map(i=>({a,i}))).slice(0,6);
    return `<section class="hero"><div class="hero-content"><div class="hero-eyebrow">Management review / October 2026</div><h1>One clear view of your writing team's content quality.</h1><p>Compare four writers, open each of the 18 article audits, inspect the 8 weighted evaluation dimensions and follow every recorded finding back to its evidence and correction.</p></div><div class="hero-stamp"><strong>${fixed(t.article_weighted_average)}</strong><small>Article-weighted mean / 100</small></div></section>
    <div class="stats">${stat('Articles reviewed',fmt(t.articles),'Across four assigned writers')}${stat('Strong points',fmt(t.strong_aspects),'Article–aspect ratings of 4 or 5', 'stat-accent')}${stat('Distinct mistakes',fmt(t.issues),'Deduplicated issue IDs, not failed checks')}${stat('Critical findings',fmt(t.critical),'Separate priority-review flags')}</div>
    <div class="section-row"><div><h2 class="section-title">Writer ranking</h2><p class="section-sub">Ordered by mean of original eight-dimension article scores; provisional for management calibration.</p></div><a data-link href="/rankings" class="linkline">Full comparison ${ic('arrow','icon icon-sm')}</a></div>
    <div class="grid-2"><div class="card rankings">${allWriters.map(w=>`<a data-link href="${writerUrl(w.name)}" class="rank-row"><span class="rank-n">${w.rank}</span><span><span class="person">${h(w.name)}</span><span class="person-sub">${w.article_count} audited articles · ${w.strong_aspects} strong aspects</span></span><span class="rank-track-col">${scoreBar(w.average)}</span><span class="score-strong mono">${fixed(w.average)}</span><span class="counts"><strong>${w.issue_count}</strong> issues</span></a>`).join('')}</div>
    <div class="card"><div class="card-pad"><h3 class="box-title">Review cautions</h3><p class="box-subtitle">Important qualifications before using the ranking.</p><div style="margin-top:18px;display:grid;gap:12px"><div class="note warn"><strong>Provisional scores.</strong> Editorial assessments need independent second-review calibration before HR or staffing decisions.</div><div class="note warn"><strong>Unequal samples.</strong> Maryam has 3 audited articles; other writers have 5.</div><div class="note"><strong>Source images.</strong> All exhibits are annotated source-text images, not browser-captured screenshots.</div></div><a data-link href="/criteria" class="btn" style="margin-top:18px">${ic('book')} Read scoring policy</a></div></div></div>
    <div class="section-row"><div><h2 class="section-title">Eight-dimension comparison</h2><p class="section-sub">Average 0–5 ratings by writer. This table does not count repeated checklist failures as separate deductions.</p></div></div>
    <div class="card table-wrap"><table class="matrix"><thead><tr><th>Evaluation aspect</th>${allWriters.map(w=>`<th><a data-link href="${writerUrl(w.name)}">${h(w.name)}</a></th>`).join('')}</tr></thead><tbody>${D.dimensions.map(d=>`<tr><td>${h(d.label)} <span class="muted xs">· ${d.weight}%</span></td>${allWriters.map(w=>{const x=w.dimensions.find(s=>s.key===d.key);return `<td><span class="score-cell ${(x?.average||0)<3?'low':(x?.average||0)<3.6?'mid':''}">${fixed(x?.average)}<span class="xs">/5</span></span></td>`}).join('')}</tr>`).join('')}</tbody></table></div>
    <div class="section-row"><div><h2 class="section-title">High-priority findings</h2><p class="section-sub">A selection of recorded critical issues. Open a finding to inspect evidence and the recommended change.</p></div><a href="/rankings" data-link class="linkline">View all writers ${ic('arrow','icon icon-sm')}</a></div>
    <div class="grid-2"><div class="card risk-list">${crit.map(({a,i})=>`<a data-link href="${articleUrl(a)}?issue=${encodeURIComponent(i.issue_id)}" class="risk-item"><span class="risk-flag">${ic('alert')}</span><span><span class="risk-title">${h(i.title)}</span><span class="risk-sub">${h(a.writer)} · ${h(maxLine(a.title,60))} · ${h(i.issue_id)}</span></span><span style="margin-left:auto;color:#9aa8b7">${ic('chevron')}</span></a>`).join('')}</div><div class="card card-pad"><h3 class="box-title">Audit coverage</h3><p class="box-subtitle">Every diagnostic status is retained in the article pages.</p><div style="display:grid;gap:14px;margin-top:20px">${[['Passed checks',t.passed_checks,'#2d9c77'],['Failed checks',t.failed_checks,'#c87569'],['Not verified',t.not_verified_checks,'#d1a85e'],['Not applicable',t.na_checks,'#a4afba']].map(([name,count,color])=>`<div><div class="fullbar"><span class="small">${h(name)}</span><strong class="mono">${fmt(count)}</strong></div><div class="barline" style="margin-top:7px"><span style="width:${count/(52*18)*100}%;background:${color}"></span></div></div>`).join('')}</div><div class="note" style="margin-top:20px">The checklist contains <strong>936 records</strong> (${t.articles} articles × 52 checks); the unique issue register contains ${t.issues} independently recorded findings. Some failed checks lack individual issue cross-references and are flagged for follow-up in article checklists.</div></div></div>`;
  }

  function rankings(){return `<div class="page-head"><div><div class="eyebrow">Cross-writer evaluation</div><h1 class="page-title">Writer rankings</h1><p class="subhead">Four writers compared on identical eight-dimension scoring weights. Article counts and evidence limitations remain visible so rankings are not mistaken for validated personnel decisions.</p></div><div class="right"><button class="btn" data-action="export-csv">${ic('export')} Export ranking CSV</button></div></div>
  <section class="hero" style="min-height:170px"><div class="hero-content"><div class="hero-eyebrow">Relative position ≠ passing the benchmark</div><h2 style="margin:0 0 11px;font-size:25px;letter-spacing:-.7px">${h(allWriters[0].name)} leads this provisional sample at ${fixed(allWriters[0].average)}/100.</h2><p>The suggested minimum is ${threshold}/100 and is adjustable on the criteria page. A writer can rank first and still be below that benchmark.</p></div><div class="hero-stamp"><strong>#1</strong><small>Relative sample rank</small></div></section>
  <div class="section-row"><h2 class="section-title">Four-writer comparison</h2><a data-link href="/criteria" class="linkline">Scoring definitions ${ic('arrow','icon icon-sm')}</a></div>
  <div class="card table-wrap"><table><thead><tr><th>Rank</th><th>Writer</th><th>Avg. /100</th><th>Articles</th><th>Strong aspects</th><th>Unique issues</th><th>Critical</th><th>Suggested benchmark</th></tr></thead><tbody>${allWriters.map(w=>`<tr><td><strong>#${w.rank}</strong></td><td><a data-link href="${writerUrl(w.name)}" class="linkline">${h(w.name)} ${ic('arrow','icon icon-sm')}</a></td><td><strong style="font-size:18px">${fixed(w.average)}</strong></td><td>${w.article_count}${w.article_count!==5?' <span class="badge nv">Smaller sample</span>':''}</td><td style="color:var(--green)"><strong>${w.strong_aspects}</strong></td><td style="color:var(--red)"><strong>${w.issue_count}</strong></td><td>${w.critical_count}</td><td>${thresholdLabel(w.average,w.critical_count)}</td></tr>`).join('')}</tbody></table></div>
  <div class="section-row"><h2 class="section-title">Strength & issue profiles</h2></div>
  <div class="grid-2-equal">${allWriters.map(w=>`<a data-link href="${writerUrl(w.name)}" class="card card-pad"><div class="fullbar"><div class="identity-row" style="gap:10px"><span class="writer-initial" style="width:41px;height:41px;font-size:14px">${avatar(w.name)}</span><span><strong style="font-size:15px">${h(w.name)}</strong><div class="muted xs">${w.article_count} articles · Rank #${w.rank}</div></span></div><span style="font-weight:820;font-size:27px">${fixed(w.average)}</span></div><div style="margin:18px 0 12px">${scoreBar(w.average)}</div><div class="fullbar" style="font-size:11px"><span style="color:var(--green)"><strong>${w.strong_aspects}</strong> strong rated aspects</span><span style="color:var(--red)"><strong>${w.issue_count}</strong> distinct mistakes</span></div><div style="margin-top:16px" class="muted xs">Common: ${h(w.repeat_themes.slice(0,2).map(t=>t.label).join(' · '))}</div></a>`).join('')}</div>
  <div class="section-row"><h2 class="section-title">Dimension-by-dimension comparison</h2></div>
  <div class="card table-wrap"><table class="matrix"><thead><tr><th>Dimension (weight)</th>${allWriters.map(w=>`<th>${h(w.name)}</th>`).join('')}</tr></thead><tbody>${D.dimensions.map(d=>`<tr><td>${h(d.label)} <span class="muted xs">(${d.weight}%)</span></td>${allWriters.map(w=>{const x=w.dimensions.find(x=>x.key===d.key);return `<td><span class="score-cell ${x.average<3?'low':x.average<3.6?'mid':''}">${fixed(x.average)}/5</span><div class="xs muted" style="margin-top:5px">${x.pass} pass / ${x.fail} fail</div></td>`}).join('')}</tr>`).join('')}</tbody></table></div>
  <div class="note warn" style="margin-top:18px">The score is the average of existing article ratings, not a percentage of passes or failures. Repeated mistakes are grouped as unique issue IDs; the writer ranking is provisional and sample-size differences matter.</div>`;
  }

  function writerProfile(w){const arts=w.article_ids.map(getArticle);const primaryStrong=w.dimensions.filter(d=>d.average>=3.5).sort((a,b)=>b.average-a.average);
    return `<div class="page-head"><div><div class="eyebrow">Writer profile / Relative rank #${w.rank}</div><h1 class="page-title">${h(w.name)} — editorial evaluation</h1><p class="subhead">Eight scoring dimensions, recurring patterns, verified evidence and individual article results. All source ratings remain provisional.</p></div><div class="right" style="display:flex;gap:7px;flex-wrap:wrap"><button data-action="export-writer" data-writer="${w.slug}" class="btn">${ic('export')} Export writer JSON</button><button data-action="print" class="btn">${ic('print')} Print</button></div></div>
    <div class="writer-hero"><div class="identity-row"><div class="writer-initial">${avatar(w.name)}</div><div><div class="writer-head-title">${h(w.name)}</div><div class="writer-metadata">${w.article_count} assigned articles reviewed · Provisional rank #${w.rank} of 4</div><div style="margin-top:9px">${thresholdLabel(w.average,w.critical_count)} ${w.article_count!==5?statusBadge('nv','3-ARTICLE SAMPLE'):''}</div></div></div><div class="writer-score"><big>${fixed(w.average)}</big><small>Average weighted score /100</small></div></div>
    <div class="writer-stat-grid"><div class="card writer-stat"><b style="color:var(--green)">${w.strong_aspects}</b><span>Strong points · article-aspect ratings ≥4</span></div><div class="card writer-stat"><b style="color:var(--red)">${w.issue_count}</b><span>Distinct recorded mistakes</span></div><div class="card writer-stat"><b>${w.passed_checks}</b><span>Passed diagnostic checks</span></div><div class="card writer-stat"><b>${w.critical_count}</b><span>Critical findings flagged</span></div></div>
    <div class="section-row"><div><h2 class="section-title">Eight evaluation aspects</h2><p class="section-sub">An aspect is PASS at 3/5 or above, FAIL below 3/5; the 3/5 rule is a suggested display convention. N/A remains distinct.</p></div><a data-link href="/criteria" class="linkline">View weights & criteria ${ic('arrow','icon icon-sm')}</a></div>
    <div class="aspect-grid">${w.dimensions.map(s=>{const d=D.dimensions.find(x=>x.key===s.key);const cases=arts.flatMap(a=>a.issues.filter(i=>i.primary_dimension===s.key).map(i=>({a,i})));return `<div class="card aspect-card"><div class="aspect-head"><div><div class="aspect-title">${h(s.label)}</div><div class="aspect-meta">${s.weight}% weight · ${s.pass} PASS · ${s.fail} FAIL${s.na?' · '+s.na+' N/A':''}</div></div><div class="aspect-avg">${fixed(s.average)}<span class="xs muted">/5</span></div></div>${percentBar(s.average)}<div class="aspect-foot"><span>${cases.length} associated distinct findings</span><span>${statusBadge(s.average>=3?'pass':'fail',s.average>=3?'AVG PASS':'AVG FAIL')}</span></div>${cases.length?`<div style="border-top:1px solid var(--line2);padding-top:12px;margin-top:13px" class="small muted"><strong style="color:var(--ink)">Example:</strong> ${h(maxLine(cases[0].i.title,110))}<br><a class="linkline" data-link href="${articleUrl(cases[0].a)}?issue=${encodeURIComponent(cases[0].i.issue_id)}">Evidence in article ${ic('arrow','icon icon-sm')}</a></div>`:''}<div style="border-top:1px solid var(--line2);padding-top:9px;margin-top:12px"><div class="xs muted" style="font-weight:750;margin-bottom:5px">Article-by-article ratings</div>${arts.map(a=>{const rating=a.scoring.find(r=>r.key===s.key);return `<a data-link href="${articleUrl(a)}" class="fullbar" style="font-size:11px;padding:5px 0;gap:8px"><span class="muted">Article ${a.number}</span><span>${rating.rating===null?'N/A':rating.rating+'/5'} &nbsp; ${statusBadge(rating.status)}</span></a>`}).join('')}</div></div>`}).join('')}</div>
    <div class="section-row"><div><h2 class="section-title">Repeated mistakes across articles</h2><p class="section-sub">Similar issues grouped by subject, counted once per underlying finding. These patterns do not create additional score deductions.</p></div></div>
    <div class="grid-2-equal">${w.repeat_themes.slice(0,6).map(t=>`<div class="card repeat-card"><div class="repeat-top"><div class="eyebrow" style="margin:0">Recurring pattern</div><span class="repeat-num">${t.articles_affected} / ${w.article_count} articles</span></div><div class="repeat-title">${h(t.label)}</div><p class="muted xs" style="margin:0">${t.issue_count} distinct findings tagged in this theme; the same finding may appear under another descriptive theme without extra penalties.</p><div class="repeat-examples">${t.examples.slice(0,3).map(x=>`<a data-link href="${articleUrl(getArticle(x.article_id))}?issue=${encodeURIComponent(x.issue_id)}" class="repeat-example"><strong>${h(maxLine(x.title,100))}</strong>${h(maxLine(x.article_title,82))} ${ic('arrow','icon icon-sm')}</a>`).join('')}</div></div>`).join('')}</div>
    <div class="section-row"><div><h2 class="section-title">Strengths observed in the articles</h2><p class="section-sub">These are the original qualitative summaries, shown alongside the stronger rated aspects.</p></div></div>
    <div class="grid-2"><div class="card card-pad"><h3 class="box-title">Strongest rated dimensions</h3><p class="box-subtitle">Writer-level averages, not a new overall score</p><div style="margin-top:18px;display:grid;gap:17px">${[...w.dimensions].sort((a,b)=>b.average-a.average).slice(0,5).map(s=>`<div><div class="fullbar" style="margin-bottom:7px"><strong class="small">${h(s.label)}</strong><span class="small mono">${fixed(s.average)} / 5</span></div>${percentBar(s.average)}</div>`).join('')}</div></div><div class="card card-pad"><h3 class="box-title">Positive article observations</h3><div style="margin-top:13px;display:grid;gap:12px">${arts.map(a=>`<div style="border-bottom:1px solid var(--line2);padding:0 0 11px"><a data-link href="${articleUrl(a)}" class="linkline">${h(maxLine(a.title,68))} ${ic('arrow','icon icon-sm')}</a><div class="small muted" style="margin-top:5px">${h(maxLine(a.summary?.strengths,250))}</div></div>`).join('')}</div></div></div>
    <div class="section-row"><div><h2 class="section-title">All ${w.article_count} article evaluations</h2><p class="section-sub">Open an article to inspect 8 aspect decisions, the complete 52-check record, evidence and actions.</p></div></div>
    <div class="article-list">${arts.map(a=>`<a data-link class="card article-link" href="${articleUrl(a)}"><span class="article-number">${String(a.number).padStart(2,'0')}</span><span><span class="article-name">${h(a.title)}</span><span class="article-keyword">${h(a.keyword||a.url)}</span></span><span class="article-col-b mono">${fixed(a.score)}<small>/100 score</small></span><span class="article-col-b extra-col">${a.counts.strong_aspects}<small>strong aspects</small></span><span class="article-col-b extra-col">${a.counts.issues}<small>unique issues</small></span><span style="color:#83a39b">${ic('chevron')}</span></a>`).join('')}</div>
    <div class="note warn" style="margin-top:20px">${w.article_count===3?'Only three articles are available for this writer; avoid equating the sample with a five-article review. ':''}The repeated-pattern labels use an explicit keyword grouping of existing issue titles and rationales and should be reviewed by an editor; this does not modify the original scoring or count issues twice.</div>`;
  }

  function articlePage(a){const w=getWriter(slug(a.writer));const jump=new URLSearchParams(location.search).get('issue');if(jump){articleTab='issues';viewedIssue=jump;}
    return `<div class="page-head"><div><div class="eyebrow"><a data-link href="${writerUrl(a.writer)}">${h(a.writer)} / Article ${a.number}</a></div><h1 class="page-title" style="font-size:30px;margin-bottom:9px">Article-level quality assessment</h1><p class="subhead">All original verdicts and issue evidence, organized by eight weighted aspects, nine diagnostic sections, and correction priority.</p></div><div class="right" style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" data-action="export-article" data-id="${a.id}">${ic('export')} Export report JSON</button><a class="btn" href="${originalUrl(a)}" download="${h(a.id)}-original-audit.json">${ic('file')} Original audit JSON</a><a class="btn" href="${h(a.url)}" target="_blank" rel="noopener noreferrer">${ic('external')} Live article</a></div></div>
    <div class="article-hero"><div class="article-hero-line"><span class="badge review">${h(a.writer)} · Article ${String(a.number).padStart(2,'0')}</span>${thresholdLabel(a.score,a.counts.critical)}<span class="muted xs">Reviewed ${h(a.date||'October 2026')}</span></div><h1>${h(a.title)}</h1><div class="small muted"><strong>Target query:</strong> ${h(a.keyword||'Not assigned')} <span style="margin:0 7px">·</span><strong>Audience:</strong> ${h(a.audience||'US B2B packaging buyers')}</div><div class="article-kpi"><div><span class="num">${fixed(a.score)}</span><label>Score /100</label></div><div><span class="num" style="color:var(--green)">${a.counts.strong_aspects}</span><label>Strong rated aspects</label></div><div><span class="num" style="color:var(--red)">${a.counts.issues}</span><label>Distinct mistakes</label></div><div><span class="num">${a.counts.passed_checks}</span><label>PASS checks /52</label></div><div><span class="num">${a.counts.not_verified_checks+a.counts.na_checks}</span><label>Unverified / N/A</label></div></div></div>
    <nav class="article-sect-tabs" aria-label="Article details">${[['summary','Executive summary'],['aspects','8 evaluation aspects'],['issues',`${a.counts.issues} issues & evidence`],['checklist','52 checks'],['actions','Correction plan']].map(([key,label])=>`<button data-action="article-tab" data-tab="${key}" class="tab ${articleTab===key?'active':''}">${h(label)}</button>`).join('')}</nav>
    <div id="article-panel">${articleTabContent(a)}</div>`;
  }
  function articleTabContent(a){switch(articleTab){case'aspects':return articleAspects(a);case'issues':return articleIssues(a);case'checklist':return articleChecklist(a);case'actions':return articleActions(a);default:return articleSummary(a);}}
  function articleSummary(a){const important=a.issues.filter(i=>i.severity==='critical'||i.severity==='major').slice(0,4);return `<div class="summary-grid"><div class="card summary-box"><h3>${ic('bulb')} Strong points</h3><p>${h(a.summary.strengths||'No qualitative strengths recorded.')}</p></div><div class="card summary-box"><h3>${ic('alert')} Critical findings</h3><p>${h(a.summary.critical_findings||'No qualitative findings recorded.')}</p></div><div class="card summary-box full"><h3>${ic('target')} Recommended corrections</h3><p>${h(a.summary.recommended_corrections||'No corrective summary recorded.')}</p></div></div><div class="section-row"><h2 class="section-title">Eight aspects at a glance</h2><button data-action="article-tab" data-tab="aspects" class="btn btn-sm">Inspect every aspect ${ic('arrow','icon icon-sm')}</button></div><div class="card table-wrap"><table><thead><tr><th>Dimension</th><th>Weight</th><th>Rating</th><th>Verdict</th><th>Weighted points</th></tr></thead><tbody>${a.scoring.map(s=>`<tr><td style="font-weight:700">${h(s.label)}</td><td>${s.weight}%</td><td>${s.rating===null?'—':s.rating+'/5'}</td><td>${statusBadge(s.status)}</td><td class="mono">${s.points===null?'—':fixed(s.points)}</td></tr>`).join('')}</tbody></table></div><div class="section-row"><h2 class="section-title">Top-priority corrections</h2><button data-action="article-tab" data-tab="issues" class="btn btn-sm">All ${a.counts.issues} findings ${ic('arrow','icon icon-sm')}</button></div><div class="grid-2-equal">${important.map(i=>`<div class="card card-pad"><div class="fullbar">${severityBadge(i.severity)}<span class="mono-label muted">${h(i.issue_id)}</span></div><h3 style="font-size:14px;margin:13px 0 6px">${h(i.title)}</h3><p class="small muted">${h(maxLine(i.reason,220))}</p><div class="recommended"><strong>Correction:</strong> ${h(maxLine(i.recommended_action,240))}</div><button class="btn btn-sm" style="margin-top:13px" data-action="show-issue" data-issue="${h(i.issue_id)}">View source evidence ${ic('arrow','icon icon-sm')}</button></div>`).join('')}</div><div class="note warn" style="margin-top:20px">Source caveat: evidence PNGs are annotated verbatim excerpts, not rendered-page screenshots. Link-destination and external specification checks may remain Not verified, and writer attribution is based on the internal assignment.</div>`;}

  function articleAspects(a){return `<div class="section-row" style="margin-top:8px"><div><h2 class="section-title">Eight evaluated aspects</h2><p class="section-sub">A rating ≥3/5 displays PASS; below 3/5 displays FAIL. This rule is a proposed interpretation; the original 0–5 ratings and rationales are preserved.</p></div></div><div style="display:grid;gap:12px">${a.scoring.map((s,n)=>{const matching=a.issues.filter(i=>i.primary_dimension===s.key);return `<div class="card aspect-detail"><div class="aspect-detail-head"><div style="display:flex;align-items:center;gap:12px"><span class="article-number">${String(n+1).padStart(2,'0')}</span><span><strong style="font-size:14px">${h(s.label)}</strong><div class="muted xs">${s.weight}% of total article score</div></span></div><div style="display:flex;align-items:center;gap:13px">${statusBadge(s.status)}<strong style="font-size:19px" class="mono">${s.rating===null?'—':s.rating+'/5'}</strong></div></div><div class="aspect-detail-content"><div class="aspect-rationale"><strong>Rationale:</strong> ${h(s.rationale||'No rationale recorded.')}<br><span class="muted xs">Contribution: ${s.points===null?'N/A':fixed(s.points)} out of ${s.weight} weighted points.</span></div>${matching.length?`<strong class="xs" style="text-transform:uppercase;letter-spacing:1px;color:#788697">Distinct issues related to this dimension (${matching.length})</strong>${matching.map(i=>`<div class="mini-issue"><div class="fullbar"><div class="mini-issue-title">${h(i.title)}</div>${severityBadge(i.severity)}</div><div class="mini-issue-desc"><strong>Reason:</strong> ${h(i.reason||'See original evidence.')}</div><div class="mini-actions"><strong>How to pass:</strong> ${h(i.recommended_action||'Editorial correction and re-review required.')}</div><button data-action="show-issue" data-issue="${h(i.issue_id)}" class="btn btn-sm" style="margin-top:10px">Open evidence ${ic('arrow','icon icon-sm')}</button></div>`).join('')}`:`<div class="note"><strong>No distinct issue is primarily assigned to this dimension.</strong> This does not prove every detail has been independently verified; see the 52 diagnostic checks.</div>`}</div></div>`}).join('')}</div>`;}

  function issueEntry(a,i){const quote=i.evidence?.map(e=>e.quote).filter(Boolean).join('\n\n')||'No excerpt provided.';const image=i.evidence?.find(e=>e.image)?.image;return `<section id="issue-${h(i.issue_id)}" class="card issue-card" data-severity="${h(i.severity)}"><div class="issue-header"><span class="issue-id">${h(i.issue_id)}</span><div style="flex:1;min-width:0"><h3 class="issue-title">${h(i.title)}</h3><div class="issue-meta">${severityBadge(i.severity)}<span class="muted xs">${h(D.dimensions.find(d=>d.key===i.primary_dimension)?.label||i.primary_dimension)}</span>${i.article_section?`<span class="muted xs">· ${h(i.article_section)}</span>`:''}</div></div></div><div class="issue-body"><div class="issue-label">Source-text evidence</div><blockquote class="issue-quote">${h(quote)}</blockquote><div class="issue-label">Why this fails / needs correction</div><div class="issue-text">${h(i.reason||'See checklist and referenced evidence.')}</div><div class="issue-label">Recommended action to pass</div><div class="recommended">${ic('target','icon icon-sm')} &nbsp; ${h(i.recommended_action||'Review and correct the documented finding.')}</div><div class="issue-footer"><div class="issue-tags"><span class="muted xs" style="padding-top:3px">Linked checks:</span>${(i.related_question_ids||[]).map(id=>`<span class="qchip">${h(id)}</span>`).join('')}</div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">${image?`<button class="evidence-button" data-action="evidence" data-image="${h(image)}" data-issue="${h(i.issue_id)}">${ic('image','icon icon-sm')} View annotated image</button>`:''}<label class="review-check" title="Local review marker; does not change scores"><input data-review="${h(a.id)}:${h(i.issue_id)}" type="checkbox" ${reviewed[a.id+':'+i.issue_id]?'checked':''}> Correction reviewed</label></div></div><div class="muted xs" style="margin-top:11px">Verification: ${h(i.verification_status||'See source limitations')} · Each issue is counted once regardless of linked checklist criteria.</div></div></section>`;}
  function articleIssues(a){const filtered=a.issues.filter(i=>issueFilter==='all'||i.severity===issueFilter);return `<div class="section-row" style="margin-top:8px"><div><h2 class="section-title">Unique issues & source evidence</h2><p class="section-sub">${a.counts.issues} distinct recorded mistakes, mapped to related diagnostic checks without double penalties.</p></div><span class="badge review">${a.counts.critical} CRITICAL</span></div><div class="checklist-toolbar"><div class="state-group">${[['all','All'],['critical','Critical'],['major','Major'],['moderate','Moderate'],['minor','Minor']].map(([v,l])=>`<button class="tab ${issueFilter===v?'active':''}" data-action="issue-filter" data-value="${v}">${l}</button>`).join('')}</div><span class="muted xs">Review checkmarks save only in this browser.</span></div><div class="issue-list">${filtered.length?filtered.map(i=>issueEntry(a,i)).join(''):'<div class="card empty">No issues match this severity filter.</div>'}</div>`;}

  function articleChecklist(a){const counts=a.counts;const groups=Object.groupBy?Object.groupBy(a.checklist,x=>x.id.split('-')[0]):a.checklist.reduce((acc,x)=>{(acc[x.id.split('-')[0]]??=[]).push(x);return acc},{});return `<div class="section-row" style="margin-top:8px"><div><h2 class="section-title">52-question diagnostic checklist</h2><p class="section-sub">All source verdicts are retained: ${counts.passed_checks} PASS, ${counts.failed_checks} FAIL, ${counts.na_checks} N/A, ${counts.not_verified_checks} Not verified.</p></div></div><div class="checklist-toolbar"><div class="search-field">${ic('search')}<input id="check-search" class="input" placeholder="Search criteria, evidence or IDs…" value="${h(checkSearch)}" type="search" aria-label="Search checklist"></div><select id="check-filter" class="select" aria-label="Filter by verdict">${[['all','All statuses'],['pass','PASS only'],['fail','FAIL only'],['na','N/A only'],['not_verified','Not verified only']].map(([k,v])=>`<option value="${k}" ${checkFilter===k?'selected':''}>${v}</option>`).join('')}</select></div><div id="checklist-content">${renderCheckGroups(a,groups)}</div>`;}
  function renderCheckGroups(a,groups){let output='';let shown=0;for(const [group,entries] of Object.entries(groups).sort((a,b)=>+a[0]-+b[0])){const match=entries.filter(x=>(checkFilter==='all'||x.status===checkFilter)&&lower([x.id,x.criterion,x.review_note,x.section,...(x.related_issue_ids||[])].join(' ')).includes(lower(checkSearch)));if(!match.length)continue;shown+=match.length;const opens=(openGroups[group]!==false);const sec=h(entries[0]?.section||'Diagnostic group '+group);output+=`<section class="card checklist-group"><button data-action="toggle-group" data-group="${group}" class="checklist-group-head"><span>Group ${+group+1}. ${sec} <small>· ${match.length} displayed / ${entries.length} checks</small></span>${ic(opens?'chevrondown':'chevron')}</button><div class="${opens?'':'hide'}">${match.map(x=>`<div class="check-item"><span class="check-id">${h(x.id)}</span><span class="check-text">${h(x.criterion)}</span><span>${statusBadge(x.status)}</span><span class="check-evidence">${h(x.review_note||'No additional observation recorded.')}${x.related_issue_ids?.length?`<div style="margin-top:6px"><strong>Issue &amp; action:</strong> ${x.related_issue_ids.map(id=>`<a href="${articleUrl(a)}?issue=${encodeURIComponent(id)}" data-link class="linkline">${h(id)}</a>`).join(' · ')}</div>`:x.status==='fail'?'<div class="note warn" style="margin-top:7px;padding:8px 10px;font-size:11px"><strong>Action gap:</strong> This failed check has no linked unique issue or recorded correction; request specific evidence and an actionable revision before closing it.</div>':''}</span></div>`).join('')}</div></section>`;}return output||'<div class="card empty">No checklist records match the filters.</div>';}

  function articleActions(a){const done=a.issues.filter(i=>reviewed[a.id+':'+i.issue_id]).length;return `<div class="section-row" style="margin-top:7px"><div><h2 class="section-title">Corrective action register</h2><p class="section-sub">${done}/${a.issues.length} manually marked reviewed in this browser. Review marks never change the original audit verdicts or score.</p></div><button data-action="export-actions" data-id="${a.id}" class="btn">${ic('export')} Export action status</button></div><div class="card table-wrap"><table><thead><tr><th>Issue</th><th>Priority</th><th>Recommended action</th><th>Review</th></tr></thead><tbody>${[...a.issues].sort((x,y)=>({critical:0,major:1,moderate:2,minor:3}[x.severity]??4)-({critical:0,major:1,moderate:2,minor:3}[y.severity]??4)).map(i=>`<tr><td><a href="${articleUrl(a)}?issue=${encodeURIComponent(i.issue_id)}" data-link class="linkline">${h(i.issue_id)} — ${h(i.title)}</a></td><td>${severityBadge(i.severity)}</td><td style="max-width:580px">${h(i.recommended_action)}</td><td><label class="review-check"><input type="checkbox" data-review="${h(a.id)}:${h(i.issue_id)}" ${reviewed[a.id+':'+i.issue_id]?'checked':''}> Reviewed</label></td></tr>`).join('')}</tbody></table></div><div class="note warn" style="margin-top:18px">Checking “Reviewed” records only a local follow-up marker, not an approved correction. To change the audit verdict, re-review the revised published article and create a new source audit version.</div>`;}

  function criteria(){const criteriaGroups=Object.groupBy?Object.groupBy(D.criterion_definitions,x=>x.id.split('-')[0]):D.criterion_definitions.reduce((o,x)=>{(o[x.id.split('-')[0]]??=[]).push(x);return o},{});
    return `<div class="page-head"><div><div class="eyebrow">Evaluation governance</div><h1 class="page-title">Criteria, weights & passing standard</h1><p class="subhead">A transparent explanation of the eight weighted assessment dimensions, all 52 diagnostic checks, deduplication policy, and the suggested minimum passing score.</p></div></div>
    <div class="note warn" style="margin-bottom:19px"><strong>Approval status:</strong> The eight scoring weights and original 0–5 ratings come from the existing audit methodology. The ${threshold}/100 passing benchmark and per-aspect PASS rule are <strong>proposed UI policies</strong>, not previously ratified management requirements.</div>
    <div class="card card-pad threshold-box"><div><div class="eyebrow">Suggested article benchmark</div><div class="threshold-value"><big id="threshold-display">${threshold}</big><span>/100 recommended minimum</span></div><p class="subhead" style="font-size:12px">Adjust this threshold to see benchmark labels throughout the dashboard. It changes <strong>no source ratings, ranking or audit data</strong> and is stored only on this device.</p></div><div><label for="threshold-slider" class="small" style="font-weight:750">Minimum total score</label><input id="threshold-slider" type="range" min="50" max="90" step="5" value="${threshold}"><div class="fullbar xs muted"><span>50 · Lenient</span><span>70 · Suggested</span><span>90 · Strict</span></div><div class="strip" style="margin-top:17px"><span class="strip-title">Aspect-level display cutoff</span><strong>3 / 5 = PASS</strong></div></div></div>
    <div class="section-row"><div><h2 class="section-title">The eight weighted dimensions</h2><p class="section-sub">Original approved weights. A human reviewer assigns each dimension an independent 0–5 rating, using the diagnostic evidence as guidance.</p></div></div>
    <div class="grid-2-equal">${D.dimensions.map((d,i)=>`<div class="card method-card"><div class="fullbar"><span class="article-number">${String(i+1).padStart(2,'0')}</span><span class="method-number">${d.weight}<span class="xs">%</span></span></div><h3>${h(d.label)}</h3><p>${h(d.description)}</p><div style="margin-top:14px" class="fullbar"><span class="xs muted">Per article: rating 0–5</span><span class="badge review">Single weighted rating</span></div></div>`).join('')}</div>
    <div class="section-row"><h2 class="section-title">What PASS / FAIL / N/A actually mean</h2></div>
    <div class="grid-2-equal"><div class="card card-pad"><h3 class="box-title">Scored aspects (8)</h3><div style="display:grid;gap:13px;margin-top:14px"><div>${statusBadge('pass')} <span class="small">Rating 3, 4 or 5 of 5. Rating 3 means acceptable with improvements.</span></div><div>${statusBadge('fail')} <span class="small">Rating 0, 1 or 2. Requires material revision.</span></div><div>${statusBadge('na')} <span class="small">No valid applicable rating exists; never automatically scored as zero.</span></div></div></div><div class="card card-pad"><h3 class="box-title">Diagnostic checks (52/article)</h3><div style="display:grid;gap:13px;margin-top:14px"><div>${statusBadge('pass')} <span class="small">The check was judged satisfied.</span></div><div>${statusBadge('fail')} <span class="small">Specific deficient evidence is recorded.</span></div><div>${statusBadge('na')} <span class="small">Not applicable to that article.</span></div><div>${statusBadge('not_verified')} <span class="small">Verification was unavailable; neither a pass nor a failure.</span></div></div></div></div>
    <div class="section-row"><h2 class="section-title">Scoring calculation & release decisions</h2></div>
    <div class="grid-2"><div class="card card-pad"><h3 class="box-title">Article score formula</h3><div style="font-size:19px;font-weight:800;color:#295f58;background:#eef6f3;padding:19px;border-radius:9px;margin:15px 0">Σ [ (dimension rating ÷ 5) × weight ]</div><p class="small muted">Eight weights total 100%. Writer score = mean of the writer's available article scores. Team article-weighted mean and writer-equal mean are different because Maryam has three audited articles.</p><hr class="divider"><h3 class="box-title">No duplicate deductions</h3><p class="small muted">A single issue ID can justify multiple diagnostic FAIL entries, but the same defect is recorded only once in the unique issue register. Existing holistic ratings are not recalculated by counting failures.</p></div><div class="card card-pad"><h3 class="box-title">Suggested editorial decision policy</h3><div style="display:grid;gap:13px;margin-top:13px"><div class="strip"><span class="strip-title">Numerical passing benchmark</span><strong>≥ ${threshold}/100</strong></div><div class="strip"><span class="strip-title">Aspect-level PASS</span><strong>≥ 3/5</strong></div><div class="strip"><span class="strip-title">Any open critical error</span><strong>Escalate review</strong></div><div class="strip"><span class="strip-title">Unverified evidence</span><strong>Do not assume PASS</strong></div></div><div class="note warn" style="margin-top:14px">These are recommendations for management to approve—not pre-existing employment standards or a claim that all sources were independently verified.</div></div></div>
    <div class="section-row"><div><h2 class="section-title">Complete 52-point diagnostic register</h2><p class="section-sub">Checklist labels as recorded in the original audit packages, grouped by their nine source sections. This does not substitute for the eight weighted dimensions.</p></div></div>
    <div class="card table-wrap"><table class="method-table"><thead><tr><th>ID</th><th>Diagnostic section</th><th>Question / criterion</th></tr></thead><tbody>${D.criterion_definitions.map(x=>`<tr><td class="mono-label">${h(x.id)}</td><td>${h(x.section)}</td><td>${h(x.text)}</td></tr>`).join('')}</tbody></table></div>`;}

  function about(){return `<div class="page-head"><div><div class="eyebrow">Data provenance</div><h1 class="page-title">About the review data</h1><p class="subhead">What this platform contains, what was preserved, and what is not verified.</p></div></div><div class="grid-2-equal"><div class="card card-pad"><h3 class="box-title">Included inputs</h3><p class="small muted">Consolidated from the four attached re-audit packages covering Fizza (5 articles), Mohsin (5), Hassan (5), and Maryam (3). Every article's 52 diagnostic verdicts, eight ratings, unique findings, evidence excerpts, and correction actions are retained.</p><div class="note" style="margin-top:17px">You can download original individual audit files from each article page as well as the normalized overall dataset from the top navigation.</div></div><div class="card card-pad"><h3 class="box-title">Evidence media</h3><p class="small muted">The included 168 PNG exhibits reproduce and annotate passages from the audited text. They are <strong>not live-page screenshots</strong>. Clicking an exhibit opens the original archived annotated image; links to the published articles remain available for independent checking. Thirty-three failed diagnostic checks have no linked unique issue ID; these remain visible with an action-mapping warning, not silently reconciled.</p><div class="note warn" style="margin-top:17px">Source verification caveats, where recorded, remain visible in every article's exported JSON. No external technical validation has been invented.</div></div><div class="card card-pad"><h3 class="box-title">Writer identification</h3><p class="small muted">Writer attribution is based on the assignments provided for this review. Public article bylines can differ and should not be used to assign editorial responsibility without confirming the production workflow.</p></div><div class="card card-pad"><h3 class="box-title">Data integrity & updating</h3><p class="small muted">This is a static, read-only Vercel application. The source ratings and mistakes are not editable in the browser. Optional “Correction reviewed” checkmarks are stored only on your local device and do not update shared data. To publish new results, replace/rebuild the static dataset.</p></div></div><div class="section-row"><h2 class="section-title">Recorded review counts</h2></div><div class="stats">${stat('Articles',D.totals.articles,'5 + 5 + 5 + 3')}${stat('Unique issues',D.totals.issues,'Issue IDs, deduplicated')}${stat('Checklist records',D.totals.articles*52,'52 per article')}${stat('Not verified',D.totals.not_verified_checks,'Not treated as failures')}</div><div class="note warn" style="margin-top:18px">The scores are provisional editorial judgments. To use them in performance management, implement a blinded or independent second-review calibration, confirm article attribution and sampling equivalence, and approve the passing policy.</div>`;}

  function err404(){return `<div class="card card-pad" style="text-align:center;padding:60px 30px"><h1 class="page-title">Page not found</h1><p class="subhead" style="margin:0 auto 25px">That audit route is not in the current dataset.</p><a href="/" class="btn btn-primary" data-link>Return to overview</a></div>`;}
  function render(opts={}){const route=parseRoute();let content; if(route.type==='home')content=dashboard();else if(route.type==='rankings')content=rankings();else if(route.type==='criteria')content=criteria();else if(route.type==='about')content=about();else if(route.type==='writer'){const w=getWriter(route.writer);content=w?writerProfile(w):err404()}else if(route.type==='article'){const a=articles.find(a=>slug(a.writer)===route.writer&&a.number===route.number);content=a?articlePage(a):err404()}else content=err404();root.innerHTML=appShell(route,content);document.title=(route.type==='article'?articles.find(a=>slug(a.writer)===route.writer&&a.number===route.number)?.title:route.type==='writer'?getWriter(route.writer)?.name:route.type==='criteria'?'Evaluation criteria':route.type==='rankings'?'Writer rankings':'Overview')+' · Print247 Review';if(!opts.preserveScroll)window.scrollTo({top:0,behavior:'instant'});if(route.type==='article'&&viewedIssue&&articleTab==='issues'){requestAnimationFrame(()=>{const el=document.getElementById('issue-'+viewedIssue);if(el)el.scrollIntoView({behavior:'smooth',block:'start'});viewedIssue=null;});}}
  function navigate(href){const url=new URL(href,location.origin);if(url.origin!==location.origin){location.href=href;return;}history.pushState(null,'',url.pathname+url.search+url.hash);menuOpen=false;if(!url.searchParams.has('issue')){articleTab='summary';viewedIssue=null;}checkFilter='all';checkSearch='';issueFilter='all';render();}
  function asDownload(filename,value,type='application/json'){const blob=new Blob([value],{type});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;document.body.appendChild(link);link.click();setTimeout(()=>{URL.revokeObjectURL(link.href);link.remove()},1000);}
  function updateArticlePanel(){const route=parseRoute();const a=articles.find(a=>slug(a.writer)===route.writer&&a.number===route.number);if(!a)return;const holder=document.getElementById('article-panel');if(holder)holder.innerHTML=articleTabContent(a);document.querySelectorAll('.article-sect-tabs .tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===articleTab));}
  function modalImage(issueId,image){const a=articles.find(a=>a.issues.some(i=>i.issue_id===issueId));const i=a?.issues.find(i=>i.issue_id===issueId);const e=i?.evidence?.find(e=>e.image===image);modalRoot.innerHTML=`<div class="modal-screen" data-action="close-modal"><div class="modal-box" role="dialog" aria-modal="true" aria-label="Annotated evidence for ${h(issueId)}"><div class="modal-head"><div><strong>${h(issueId)} · ${h(i?.title||'Evidence')}</strong><small>Annotated article excerpt — not a live webpage screenshot.</small></div><button class="btn btn-sm" aria-label="Close evidence" data-action="close-modal">${ic('x')}</button></div><div class="modal-picture"><img alt="Annotated textual evidence for ${h(issueId)}" src="${h(image)}" loading="eager"></div><div class="small muted" style="padding:14px 20px">Source: <a class="source-link" href="${h(e?.source_url||a?.url)}" rel="noopener noreferrer" target="_blank">Open published article ${ic('external','icon icon-sm')}</a> · Please verify any high-stakes factual claim independently before a personnel decision.</div></div></div>`;}
  document.addEventListener('click',event=>{
    const link=event.target.closest('a[data-link]');if(link){event.preventDefault();navigate(link.getAttribute('href'));return;}
    const control=event.target.closest('[data-action]');if(!control)return;
    const action=control.dataset.action;
    if(action==='menu'){menuOpen=!menuOpen;render({preserveScroll:true});return;}
    if(action==='closemenu'){menuOpen=false;render({preserveScroll:true});return;}
    if(action==='print'){window.print();return;}
    if(action==='article-tab'){articleTab=control.dataset.tab;issueFilter='all';updateArticlePanel();return;}
    if(action==='show-issue'){articleTab='issues';issueFilter='all';updateArticlePanel();const el=document.getElementById('issue-'+control.dataset.issue);el?.scrollIntoView({behavior:'smooth',block:'start'});return;}
    if(action==='issue-filter'){issueFilter=control.dataset.value;updateArticlePanel();return;}
    if(action==='toggle-group'){openGroups[control.dataset.group]=openGroups[control.dataset.group]===false?true:false;const route=parseRoute();const a=articles.find(a=>slug(a.writer)===route.writer&&a.number===route.number);if(a){const groups=a.checklist.reduce((o,x)=>{(o[x.id.split('-')[0]]??=[]).push(x);return o},{});document.getElementById('checklist-content').innerHTML=renderCheckGroups(a,groups);}return;}
    if(action==='evidence'){modalImage(control.dataset.issue,control.dataset.image);return;}
    if(action==='close-modal'){if(event.target===control||control.closest('button'))modalRoot.innerHTML='';return;}
    if(action==='export-overall'){asDownload('print247-editorial-review-data.json',JSON.stringify(D,null,2));return;}
    if(action==='export-writer'){const w=getWriter(control.dataset.writer);if(w)asDownload(`print247-${w.slug}-writer-review.json`,JSON.stringify({writer:w,articles:w.article_ids.map(getArticle),methodology:D.meta,dimensions:D.dimensions},null,2));return;}
    if(action==='export-article'){const a=getArticle(control.dataset.id);if(a)asDownload(`print247-${a.id}-article-audit.json`,JSON.stringify(a,null,2));return;}
    if(action==='export-actions'){const a=getArticle(control.dataset.id);if(a)asDownload(`print247-${a.id}-correction-progress.json`,JSON.stringify({article_id:a.id,local_only:true,items:a.issues.map(i=>({issue_id:i.issue_id,title:i.title,action:i.recommended_action,reviewed_on_this_device:!!reviewed[a.id+':'+i.issue_id]}))},null,2));return;}
    if(action==='export-csv'){const rows=[['Rank','Writer','Provisional score /100','Articles','Strong aspects >=4/5','Unique issues','Critical issues','Passed checks','Failed checks'],...allWriters.map(w=>[w.rank,w.name,w.average,w.article_count,w.strong_aspects,w.issue_count,w.critical_count,w.passed_checks,w.failed_checks])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');asDownload('print247-writer-ranking.csv',csv,'text/csv');return;}
  });
  document.addEventListener('change',event=>{
    const el=event.target;
    if(el.matches('[data-review]')){reviewed[el.dataset.review]=!!el.checked;try{localStorage.setItem('p247_reviewed',JSON.stringify(reviewed))}catch(e){}return;}
    if(el.id==='check-filter'){checkFilter=el.value;refreshChecklist();return;}
    if(el.id==='threshold-slider'){threshold=+el.value;try{localStorage.setItem('p247_threshold',String(threshold))}catch(e){}render({preserveScroll:true});return;}
  });
  document.addEventListener('input',event=>{
    const el=event.target;
    if(el.id==='check-search'){checkSearch=el.value;refreshChecklist();return;}
    if(el.id==='threshold-slider'){const disp=document.getElementById('threshold-display');if(disp)disp.textContent=el.value;}
  });
  function refreshChecklist(){const route=parseRoute();const a=articles.find(a=>slug(a.writer)===route.writer&&a.number===route.number);if(!a)return;const groups=a.checklist.reduce((o,x)=>{(o[x.id.split('-')[0]]??=[]).push(x);return o},{});const pane=document.getElementById('checklist-content');if(pane)pane.innerHTML=renderCheckGroups(a,groups);}
  window.addEventListener('popstate',()=>{articleTab=new URLSearchParams(location.search).has('issue')?'issues':'summary';render();});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')modalRoot.innerHTML='';});
  render();
})();
